cd "$HOME/mnt/corp-site/ad-lp" && python3 - <<'PY'
import base64
sec=base64.b64decode("").decode()
css=base64.b64decode("").decode()
hero=base64.b64decode("").decode()
h=open('index.html',encoding='utf-8').read()
key='<!-- ============ 成果事例（横スクロール） ============ -->'
assert h.count(key)==1 and 'ad-sample' not in h
h=h.replace(key, sec+key)
h=h.replace('href="style.css?v=8"','href="style.css?v=9"')
open('index.html','w',encoding='utf-8',newline='').write(h)
s=open('style.css',encoding='utf-8').read()
assert 'ad-sample' not in s
s=s.rstrip('\n')+'\n'+hero+css
open('style.css','w',encoding='utf-8',newline='').write(s)
print('ok')
PY
